<?php require 'config.php';if(empty($_SESSION['admin_id']))go('admin_login.php');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$st=$_POST['status']??'';$rem=trim($_POST['remarks']??'');if(in_array($st,['Pending','In Progress','Resolved','Rejected'],true)){$s=$pdo->prepare('UPDATE complaints SET status=?,admin_remarks=? WHERE id=?');$s->execute([$st,$rem?:null,$id]);msg('Complaint updated.');go('admin_complaints.php');}}$rows=$pdo->query('SELECT c.*,u.name,u.email FROM complaints c JOIN users u ON u.id=c.user_id ORDER BY c.id DESC')->fetchAll();$title='Manage Complaints';require 'partials/top.php';?><section class="glass panel"><h3>Manage Complaints</h3><p>Update the status and remarks for each submission.</p><?php foreach($rows as $r):?><article class="glass complaint"><div><b><?=e($r['complaint_code'])?> · <?=e($r['title'])?></b><p><?=e($r['name'])?> · <?=e($r['department'])?> · <?=e($r['category'])?></p><p><?=nl2br(e($r['description']))?></p></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><label>Status</label><select name="status"><?php foreach(['Pending','In Progress','Resolved','Rejected'] as $st):?><option <?=$r['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><label>Admin remarks</label><textarea name="remarks" rows="2"><?=e($r['admin_remarks']??'')?></textarea><button>Save Update</button></form></article><?php endforeach;?></section><?php require 'partials/bottom.php';?>